int led = 13;

void setup() {
    pinMode(led, OUTPUT);
    Serial.begin(9600);

    // Traza de verificación del arranque
    Serial.println("Programa iniciado");
}

void loop() {
    digitalWrite(led, HIGH);
    Serial.println("LED encendido");
    delay(1000);

    digitalWrite(led, LOW);
    Serial.println("LED apagado");
    delay(1000);
}
